CREATE INDEX posts_tags_gin ON posts USING GIN (tags);
SELECT id FROM posts WHERE tags @> ARRAY['sql','database'];

CREATE INDEX users_attrs_gin ON users USING GIN (attributes jsonb_path_ops);
SELECT id FROM users WHERE attributes @> '{"color": "blue"}';

CREATE INDEX shops_loc_gist ON shops USING GIST (location);
SELECT name FROM shops ORDER BY location <-> ST_MakePoint(-122.4, 37.8) LIMIT 5;

CREATE INDEX bookings_period_gist ON bookings USING GIST (period);
SELECT * FROM bookings WHERE period && tstzrange('2026-10-11', '2026-10-12');

CREATE INDEX idx_zip_cov ON users (zipcode) INCLUDE (first_name, last_name);
EXPLAIN (ANALYZE) SELECT first_name, last_name FROM users WHERE zipcode = '90210';
--  Index Only Scan ... Heap Fetches: 4812
VACUUM ANALYZE users;   -- → Heap Fetches: 0

CREATE UNIQUE INDEX users_email_active ON users (email) WHERE deleted_at IS NULL;
CREATE INDEX orders_active ON orders (order_id) WHERE status = 'active';
-- uses it:   WHERE order_id = 12345 AND status = 'active'
-- doesn't:   WHERE order_id = 12345

SELECT s.indexrelname, pg_size_pretty(pg_relation_size(s.indexrelid)) AS size
FROM pg_stat_user_indexes s
WHERE s.idx_scan = 0
  AND NOT EXISTS (SELECT 1 FROM pg_constraint c WHERE c.conindid = s.indexrelid)
ORDER BY pg_relation_size(s.indexrelid) DESC;

DROP INDEX CONCURRENTLY events_old_idx;
